UPDATE tb_expense_resolutions
title = #{title}, resolution_date = replace(#{report_date},'-',''), dept_id = #{dept_code}, budget_id = #{budget_code}, status = #{status_code}, total_amount = #{total_amount}, updated_dt = CURRENT_TIMESTAMP
WHERE no = #{no}

UPDATE tb_expense_resolution_details
   SET acc_code = #{acc_code},
       amount = CAST(#{amount} AS NUMERIC),
       remark = #{remark}
WHERE 1=1
  AND no = #{no} 
  AND serial = #{serial}

